import 'dart:io';
import 'package:flutter/material.dart';
import 'package:path_provider/path_provider.dart';

// --- FileStorage Class (as defined above) ---
class FileStorage {
  Future<String> get _localPath async {
    final directory = await getApplicationDocumentsDirectory();
    return directory.path;
  }

  Future<File> get _localFile async {
    final path = await _localPath;
    return File('$path/note.txt');
  }

  Future<String> readNote() async {
    try {
      final file = await _localFile;
      final contents = await file.readAsString();
      return contents;
    } catch (e) {
      return '';
    }
  }

  Future<File> writeNote(String note) async {
    final file = await _localFile;
    return file.writeAsString(note);
  }
}

// --- App UI ---
void main() {
  runApp(
    const MaterialApp(
      title: 'Simple Note Taker',
      home: NoteScreen(),
    ),
  );
}

class NoteScreen extends StatefulWidget {
  const NoteScreen({super.key});

  @override
  State<NoteScreen> createState() => _NoteScreenState();
}

class _NoteScreenState extends State<NoteScreen> {
  final _storage = FileStorage();
  final _textController = TextEditingController();

  @override
  void initState() {
    super.initState();
    // Load the saved note when the app starts
    _storage.readNote().then((value) {
      setState(() {
        _textController.text = value;
      });
    });
  }

  Future<void> _saveNote() {
    setState(() {}); // Optionally update UI state if needed
    ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Note saved!')),
    );
    return _storage.writeNote(_textController.text);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('My Note')),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: TextField(
          controller: _textController,
          maxLines: 10,
          decoration: const InputDecoration(
            hintText: 'Write your note here...',
            border: OutlineInputBorder(),
          ),
        ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: _saveNote,
        tooltip: 'Save Note',
        child: const Icon(Icons.save),
      ),
    );
  }
}
